    ('068ed5980b08daf960cabdb8', 'bangla-pather-panchali', NULL, 'পথের পাঁচালী', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'নিশ্চিন্দিপুরের গ্রামীণ জীবন, অপু ও দুর্গার শৈশব এবং প্রকৃতির সঙ্গে মানুষের সম্পর্কের কালজয়ী উপন্যাস।', '/covers/bangla-pather-panchali.jpg', 'বাংলা সাহিত্য', 'উপন্যাস', 'বাংলা', 320, 8, TRUE, '2025-01-03T00:00:00.000Z'),
