    ('f5bf4dd7c7c32ef879d5dd0b', 'bangla-srikanta', NULL, 'শ্রীকান্ত', 'শরৎচন্দ্র চট্টোপাধ্যায়', 'পথিক শ্রীকান্তের ভ্রমণ, সম্পর্ক ও জীবনের অভিজ্ঞতায় সমৃদ্ধ চার খণ্ডের উপন্যাস।', '/covers/bangla-srikanta.jpg', 'বাংলা সাহিত্য', 'ভ্রমণ ও জীবন', 'বাংলা', 420, 8, TRUE, '2025-01-03T00:00:00.000Z'),
    ('c085c7e59b9e967cac0b4de3', 'bangla-aranyak', NULL, 'আরণ্যক', 'বিভূতিভূষণ বন্দ্যোপাধ্যায়', 'বিহারের অরণ্যে কাটানো দিনের স্মৃতি, প্রকৃতি ও মানুষের জীবনের এক অনন্য সাহিত্যিক আখ্যান।', '/covers/bangla-aranyak.jpg', 'বাংলা সাহিত্য', 'প্রকৃতি ও জীবন', 'বাংলা', 350, 8, TRUE, '2025-01-03T00:00:00.000Z'),
    ('f786afa7097def8e489f312a', 'bangla-feluda', NULL, 'সোনার কেল্লা', 'সত্যজিৎ রায়', 'ফেলুদা, তোপসে ও জটায়ুর সঙ্গে রাজস্থানের পথে ইতিহাস ও রহস্যে ভরা এক রোমাঞ্চকর অভিযান।', '/covers/bangla-feluda.jpg', 'বাংলা সাহিত্য', 'রহস্য ও গোয়েন্দা', 'বাংলা', 300, 8, TRUE, '2025-01-03T00:00:00.000Z'),
