INSERT INTO reviews (id, seed_key, user_id, name, email, rating, text, approved, editorial, created_at) VALUES
    ('0fd68abc99f28340417d5647', 'bookaru-editorial-hobbit', NULL, 'Booka-Ru editors', NULL, 5, 'A cozy, generous adventure with riddles, dragons, and a wonderfully unlikely hero. A lovely place to begin a fantasy reading journey.', TRUE, TRUE, '2025-01-02T00:00:00.000Z'),
    ('d15025a7beb57ce5f4435b9a', 'bookaru-editorial-secret-garden', NULL, 'Booka-Ru editors', NULL, 5, 'The Secret Garden turns curiosity and friendship into a quiet kind of magic. Its hopeful mood makes this a story readers return to.', TRUE, TRUE, '2025-01-02T00:00:00.000Z'),
    ('3e42cc5da72569a3f77b875b', 'bookaru-editorial-little-prince', NULL, 'Booka-Ru editors', NULL, 5, 'A small, thoughtful fable about friendship and seeing with your heart. The Little Prince rewards both a quick read and a slower return.', TRUE, TRUE, '2025-01-02T00:00:00.000Z'),
    ('76c44581f0281cddee717d36', 'bookaru-editorial-howls', NULL, 'Booka-Ru editors', NULL, 5, 'A witty moving castle, a spell, and characters with room to surprise you: Howl’s Moving Castle is comfort reading with plenty of sparkle.', TRUE, TRUE, '2025-01-02T00:00:00.000Z')
